DO $$ DECLARE v_form_id uuid; BEGIN
 SELECT id INTO v_form_id FROM public.dynamic_forms WHERE slug='funnel-eletrovale-eletromecanica';
 IF v_form_id IS NULL THEN INSERT INTO public.dynamic_forms (slug,name,description,status,config_json,whatsapp_config) VALUES ('funnel-eletrovale-eletromecanica','Avaliação · Eletrovale Eletromecânica','Funil individual para manutenção industrial','published','{"auto_advance_ms":250}'::jsonb,'{"enabled":true}'::jsonb) RETURNING id INTO v_form_id; ELSE UPDATE public.dynamic_forms SET status='published',name='Avaliação · Eletrovale Eletromecânica' WHERE id=v_form_id; DELETE FROM public.dynamic_form_questions WHERE form_id=v_form_id; END IF;
 INSERT INTO public.dynamic_form_questions (form_id,key,type,label,order_index,required,options_json) VALUES
 (v_form_id,'welcome','statement','Vamos avaliar seu equipamento ⚙️',0,false,'[]'::jsonb),(v_form_id,'nome','short_text','Qual é o seu nome?',1,true,'[]'::jsonb),(v_form_id,'servico','radio','Qual equipamento precisa de atenção?',2,true,jsonb_build_array(jsonb_build_object('value','motor','label','Motor elétrico'),jsonb_build_object('value','bomba','label','Bomba ou motobomba'),jsonb_build_object('value','motoredutor','label','Motoredutor ou motofreio'),jsonb_build_object('value','outro','label','Outro equipamento'))),(v_form_id,'problema','radio','O que está acontecendo?',3,true,jsonb_build_array(jsonb_build_object('value','parou','label','Parou de funcionar'),jsonb_build_object('value','ruido','label','Aquecimento ou ruído'),jsonb_build_object('value','preventiva','label','Revisão preventiva'),jsonb_build_object('value','melhoria','label','Quero melhorar o desempenho'))),(v_form_id,'local','radio','Onde está o equipamento?',4,true,jsonb_build_array(jsonb_build_object('value','curitiba','label','Curitiba e região'),jsonb_build_object('value','parana','label','Paraná'),jsonb_build_object('value','confirmar','label','Vou confirmar o endereço'))),(v_form_id,'detalhes','long_text','Mais detalhes','Envie potência, modelo ou fotos se tiver.','Descreva o equipamento',5,false,'[]'::jsonb),(v_form_id,'telefone','phone','Qual WhatsApp para retorno?',6,true,'[]'::jsonb),(v_form_id,'confirmacao','statement','Solicitação recebida! ✅','A Eletrovale confirmará os próximos passos.',7,false,'[]'::jsonb); END $$;
